I'll implement the EventProcessor to make all tests pass. Let me analyze the tests carefully and write a minimal implementation.

```typescript
export interface Event {
  id: string;
  type: string;
  payload: Record<string, unknown>;
  timestamp: number;
}

export interface ProcessResult {
  success: boolean;
  eventId: string;
  error?: string;
  retryCount?: number;
  sentToDlq?: boolean;
  duplicate?: boolean;
}

export interface RetryPolicy {
  maxRetries: number;
  delayMs: number;
}

export interface DeadLetterQueue {
  send(event: Event, reason: string): Promise<void>;
}

export type EventHandler = (event: Event) => Promise<{ success: boolean }>;

export class EventProcessor {
  private handler: EventHandler;
  private dlq: DeadLetterQueue;
  private retryPolicy: RetryPolicy;
  private processedEvents: Map<string, ProcessResult> = new Map();

  constructor(
    handler: EventHandler,
    dlq: DeadLetterQueue,
    retryPolicy?: RetryPolicy
  ) {
    this.handler = handler;
    this.dlq = dlq;
    this.retryPolicy = retryPolicy ?? { maxRetries: 0, delayMs: 0 };
  }

  async process(event: Event): Promise<ProcessResult> {
    const cached = this.processedEvents.get(event.id);
    if (cached) {
      return { ...cached, duplicate: true };
    }

    let retryCount = 0;
    let lastError: string | undefined;

    for (let attempt = 0; attempt <= this.retryPolicy.maxRetries; attempt++) {
      if (attempt > 0) {
        retryCount++;
        if (this.retryPolicy.delayMs > 0) {
          await new Promise(resolve => setTimeout(resolve, this.retryPolicy.delayMs));
        }
      }

      try {
        await this.handler(event);
        const result: ProcessResult = {
          success: true,
          eventId: event.id,
          retryCount
        };
        this.processedEvents.set(event.id, result);
        return result;
      } catch (err) {
        lastError = err instanceof Error ? err.message : String(err);
      }
    }

    await this.dlq.send(event, lastError!);
    const result: ProcessResult = {
      success: false,
      eventId: event.id,
      error: lastError,
      retryCount,
      sentToDlq: true
    };
    this.processedEvents.set(event.id, result);
    return result;
  }

  async processBatch(events: Event[]): Promise<ProcessResult[]> {
    const results: ProcessResult[] = [];
    for (const event of events) {
      results.push(await this.process(event));
    }
    return results;
  }

  isProcessed(eventId: string): boolean {
    return this.processedEvents.has(eventId);
  }
}
```

This implementation covers all test requirements:

1. **Basic Processing**: Calls handler with event, returns success/eventId
2. **Error Handling**: Catches errors, extracts message from Error objects or converts to string
3. **Retry Logic**: Retries up to maxRetries with configurable delay, tracks retryCount
4. **Dead Letter Queue**: Sends failed events to DLQ after exhausting retries, includes error reason
5. **Idempotency**: Caches results by event ID, returns cached result with `duplicate: true` for repeat calls
6. **Batch Processing**: Processes events sequentially, continues after failures, returns individual results
